import { load } from '../node_modules/@google-web-components/google-chart/google-chart-loader.js';
import '../node_modules/@polymer/polymer/lib/elements/dom-if.js';
import '../node_modules/@polymer/polymer/lib/elements/dom-repeat.js';
import {
  html,
  PolymerElement
} from '../node_modules/@polymer/polymer/polymer-element.js';
import { LoadingState } from './loading-state.js';

// Scores are generated by feature-level-interop.js in the results-analysis
// repository and published to its gh-pages branch. /api/interop-features
// fetches them from there, so that the highest-traffic page on the site reads
// a cached same-origin endpoint rather than GitHub directly.
const INTEROP_FEATURES_API = '/api/interop-features';


class WPTInteropGraph extends LoadingState(PolymerElement) {
  static get template() {
    return html`
      <style>
        :host {
          display: block;
          /* Held by the gain column whether or not a range is selected, so
             that measuring one cannot shift the scores beside it. */
          --interop-gain-width: 52px;
        }
        .container {
          display: inline-flex;
          /* Reserve vertical space to avoid layout shift while the scores load.
             Should be kept in sync with the chart height below. */
          min-height: 350px;
        }
        .left {
          width: 20%;
          margin-top: 10px;
          margin-left: 10px;
          font-size: 13px;
        }
        .chart {
          height: 350px;
          width: 800px;
        }
        .chart-area {
          position: relative;
        }
        /* Sits over the plot area while a range is being dragged, so the reader
           can see which dates the reported change covers. */
        .drag-highlight {
          position: absolute;
          background-color: var(--paper-blue-100);
          opacity: 0.35;
          pointer-events: none;
        }
        /* The dates a dragged range covers. The line is rendered whether or
           not a range is selected, so that measuring one cannot shift the
           scores below it. */
        .range-label {
          margin-left: 8px;
          font-size: 13px;
          min-height: 18px;
        }
        .browser-scores {
          margin: 6px 0 0 8px;
          font-size: 13px;
          font-variant-numeric: tabular-nums;
        }
        /* Three columns rather than two ends, so that a gain reads across from
           the score it moved and lines up with the gain above it. */
        .browser-score {
          display: grid;
          grid-template-columns: 1fr auto var(--interop-gain-width);
          column-gap: 8px;
          max-width: 210px;
        }
        .browser-score .value,
        .gain {
          text-align: right;
        }
        /* The sign already says which way a score moved, so the colour only
           reinforces it. */
        .gain.up {
          color: var(--paper-green-700);
        }
        .gain.down {
          color: var(--paper-red-700);
        }
        .headline {
          display: flex;
          align-items: baseline;
        }
        .headline .gain {
          margin-left: 8px;
          font-size: 15px;
          font-weight: bold;
          font-variant-numeric: tabular-nums;
        }
        h5 {
          margin-top: 20px;
          margin-left: 8px;
        }
        .channel {
          display: inline-flex;
          height: 35px;
          margin-top: 0px;
        }
        .unselected {
          background-color: white;
        }
        .selected {
          background-color: var(--paper-blue-100);
        }
        paper-button {
          color: black;
          text-transform: none;
        }
        .score {
          font-size: 24px;
          font-weight: bold;
          margin-left: 8px;
          margin-top: 10px;
        }
        .error {
          margin: 1em;
          color: var(--paper-grey-600);
          font-style: italic;
        }
        /* The provenance line is a heading like the rest of the sidebar, as
           wpt-bsf.js does for its last-update link. */
        h5 a {
          color: #0d5de6;
          text-decoration: none;
        }
        h5 a:hover {
          text-decoration: underline;
        }
      </style>
      <div class="container">
        <div class="left">
          <h5>Interoperability is the share of each web feature's tests that pass in every browser, averaged over features so that each counts equally. Tests only one browser passes are left out.</h5>
          <div class="headline">
            <template is="dom-if" if="[[currentScore]]">
              <div class="score">[[currentScore]]%</div>
            </template>
            <span class\$="[[gainClass(interopGain)]]">[[interopGain]]</span>
          </div>
          <h5>Feature interop gains</h5>
          <div class="range-label">[[rangeLabel]]</div>
          <div class="browser-scores">
            <template is="dom-repeat" items="[[browserRows]]">
              <div class="browser-score"><span>[[item.label]]</span><span class="value">[[item.score]]%</span><span class\$="[[gainClass(item.gain)]]">[[item.gain]]</span></div>
            </template>
          </div>
          <h5>Channel</h5>
          <div class="channel">
            <paper-button class\$="[[experimentalButtonClass(isExperimental)]]" onclick="[[clickExperimental]]">Experimental</paper-button>
            <paper-button class\$="[[stableButtonClass(isExperimental)]]" onclick="[[clickStable]]">Stable</paper-button>
          </div>
          <h5>Features from wpt's <code>WEB_FEATURES.yml</code>, scores from <a href="https://github.com/web-platform-tests/results-analysis/blob/main/feature-level-interop.js" target="_blank">results-analysis</a></h5>
          <h5>Click + drag across the graph to measure how much each browser moved over a date range</h5>
        </div>
        <div class="chart-area">
          <div id="chart" class="chart"></div>
          <div id="highlight" class="drag-highlight" hidden></div>
        </div>
        <template is="dom-if" if="[[errorMessage]]">
          <div class="error">[[errorMessage]]</div>
        </template>
      </div>
    `;
  }

  static get is() {
    return 'wpt-interop-graph';
  }

  static get properties() {
    return {
      data: Array,
      currentScore: String,
      // The newest date's score per product, shown beside the interop headline.
      currentBrowserScores: {
        type: Array,
        value: () => [],
      },
      errorMessage: String,
      // The dates the last dragged range covered, or empty when nothing is
      // selected. Its line is always rendered, so this must never be null.
      rangeLabel: {
        type: String,
        value: '',
      },
      // Score column name to the change measured across the dragged range,
      // e.g. {chrome: '+0.2'}. Empty when nothing is selected.
      rangeGains: {
        type: Object,
        value: () => ({}),
      },
      // The newest date's scores with the dragged range's change beside each,
      // so that a gain reads across from the score it moved.
      browserRows: {
        type: Array,
        computed: 'computeBrowserRows(currentBrowserScores, rangeGains)',
      },
      // Interop has the headline to itself, so its gain goes there rather than
      // into the table below.
      interopGain: {
        type: String,
        computed: 'computeInteropGain(rangeGains)',
      },
      isExperimental: {
        type: Boolean,
        value: true,
      },
      chartOptions: {
        type: Object,
        value: () => ({
          width: 800,
          height: 350,
          chartArea: {
            height: '80%',
          },
          hAxis: {
            title: 'Date',
            format: 'MMM-YYYY',
          },
          vAxis: {
            title: 'Interop Score (%)',
            minValue: 0,
            maxValue: 100,
          },
          // A hovered date shows every browser's score and the overall interop
          // score in one tooltip, rather than only the line nearest the pointer.
          focusTarget: 'category',
          colors: ['#fbc013', '#fc7a3a', '#148cda', '#333333'],
        })
      },
    };
  }

  constructor() {
    super();
    // Non-null only while a range is being dragged out.
    this.dragStartX = null;
    // The score columns the published trendline turned out to carry, in its own
    // order, so products are never hardcoded here.
    this.scoreColumnNames = [];
    this.clickStable = () => {
      if (!this.isExperimental) {
        return;
      }
      this.isExperimental = false;
      this.loadData();
    };
    this.clickExperimental = () => {
      if (this.isExperimental) {
        return;
      }
      this.isExperimental = true;
      this.loadData();
    };
  }

  ready() {
    super.ready();
    this.setUpRangeMeasure();
    // Google Charts does not reflow, so a resize needs an explicit redraw. The
    // measured range goes with it, since its highlight no longer lines up.
    window.addEventListener('resize', () => {
      this.clearRange();
      this.drawChart();
    });
    this.loadData();
  }

  stableButtonClass(isExperimental) {
    return isExperimental ? 'unselected' : 'selected';
  }

  experimentalButtonClass(isExperimental) {
    return isExperimental ? 'selected' : 'unselected';
  }

  loadData() {
    const url = new URL(INTEROP_FEATURES_API, window.location);
    if (this.isExperimental) {
      url.searchParams.set('experimental', true);
    }

    this.errorMessage = null;
    this.data = null;
    this.currentScore = null;
    this.currentBrowserScores = [];
    this.trendPoints = [];
    this.clearRange();

    this.load(
      window.fetch(url).then(
        async r => {
          if (!r.ok || r.status !== 200) {
            throw new Error(`status ${r.status}`);
          }
          return r.json();
        })
        .then(interop => {
          this.processTrendline(interop.fields, interop.data);
        }).catch(() => {
          this.errorMessage = 'Interop score data is not yet available.';
        })
    );
  }

  // The trendline's columns are sha, date and manifest, then a version and a
  // score per product, then interop. A column holds a score if the table also
  // has a version column for it, which leaves the first three out without
  // naming the products here; naming them by what they are not once let sha
  // through as a series of its own leading digits.
  scoreColumns(fields) {
    return fields.map((name, idx) => ({ name: name, idx: idx }))
      .filter(c => c.name === 'interop' ||
                   fields.includes(`${c.name}-version`));
  }

  // Builds the chart from the trendline table, one row per date in
  // chronological order, with |fields| naming its columns.
  processTrendline(fields, rows) {
    if (!fields || !rows || !rows.length) {
      this.errorMessage = 'Interop score data is empty.';
      return;
    }

    const dateIdx = fields.indexOf('date');
    const featuresIdx = fields.indexOf('features');
    const scoreColumns = this.scoreColumns(fields);
    const data = [['Date', ...scoreColumns.map(c => this.columnLabel(c.name))]];

    // Kept beside the chart's own table so a dragged range can be measured
    // against the dates actually scored, without reading back through the
    // chart's cell objects.
    const points = [];

    for (const row of rows) {
      const date = this.parseDate(row[dateIdx]);
      const scores = {};
      for (const column of scoreColumns) {
        scores[column.name] = parseFloat(row[column.idx]);
      }
      data.push([
        this.dateCell(date, featuresIdx < 0 ? '' : row[featuresIdx]),
        ...scoreColumns.map(c => scores[c.name]),
      ]);
      // A date whose interop cell did not parse is left out of the measurable
      // set, so that a dragged range cannot report a delta against a gap.
      if (Number.isFinite(scores.interop)) {
        points.push({ date: date, scores: scores });
      }
    }
    this.data = data;
    this.trendPoints = points;
    this.scoreColumnNames = scoreColumns.map(c => c.name);

    // The headline is the newest date that actually scored, so a trailing row
    // with an unreadable interop cell leaves the previous score standing rather
    // than rendering 'NaN%'.
    if (points.length) {
      const newest = points[points.length - 1];
      this.currentScore = newest.scores.interop.toFixed(1);
      this.currentBrowserScores = this.browserScoreList(newest);
    }

    this.drawChart();
  }

  // Capitalises a score column for display, so that the chart legend, the
  // headline breakdown and a dragged range all name a product the same way.
  columnLabel(name) {
    return name.charAt(0).toUpperCase() + name.slice(1);
  }

  // The newest date's score for each product, interop excluded because it has
  // the headline to itself. The column name is carried so that a dragged
  // range's gain can be matched to its score.
  browserScoreList(point) {
    return this.scoreColumnNames
      .filter(name => name !== 'interop' && Number.isFinite(point.scores[name]))
      .map(name => ({
        name: name,
        label: this.columnLabel(name),
        score: point.scores[name].toFixed(1),
      }));
  }

  // Pairs each product's newest score with what the dragged range measured for
  // it, leaving the gain empty when no range is selected.
  computeBrowserRows(scores, gains) {
    return (scores || []).map(score => ({
      label: score.label,
      score: score.score,
      gain: (gains && gains[score.name]) || '',
    }));
  }

  computeInteropGain(gains) {
    return (gains && gains.interop) || '';
  }

  // Colours a gain by direction. The sign already says which way a score
  // moved, so the colour only reinforces it.
  gainClass(gain) {
    if (!gain) {
      return 'gain';
    }

    return gain.startsWith('-') ? 'gain down' : 'gain up';
  }

  // Parses a date from the published CSV. Javascript Date objects take
  // 0-indexed months, whilst the data is 1-indexed, and the parts are read
  // individually so that a bare ISO string is not taken as UTC and shifted a
  // day in a negative timezone.
  parseDate(iso) {
    const parts = iso.split('-').map(x => parseInt(x, 10));
    return new Date(parts[0], parts[1] - 1, parts[2]);
  }

  // The one place a date becomes prose, so that the table heading and the
  // chart's tooltips cannot come to disagree about how a date reads.
  formatDate(date) {
    return date.toLocaleDateString('en-US',
      { year: 'numeric', month: 'long', day: 'numeric' });
  }

  // The heading of a hovered date's tooltip, which is the only place a reader is
  // told how many features that date's scores average over. The count moves as
  // wpt annotates features, so it belongs to the date rather than to the chart.
  // A date published before the column existed keeps the chart's own formatting.
  dateCell(date, features) {
    if (features === '') {
      return date;
    }
    return {
      v: date,
      f: `${this.formatDate(date)} (${features} features)`,
    };
  }

  // Draws the trendline directly rather than through the google-chart element,
  // which does not expose the chart's layout interface; measuring a dragged
  // range needs it to turn a pixel back into a date. interop-feature-chart.js
  // bypasses the element for the same kind of reason.
  async drawChart() {
    if (!this.data) {
      return;
    }
    await load();
    const table = window.google.visualization.arrayToDataTable(this.data);
    this.chart = new window.google.visualization.LineChart(this.$.chart);
    this.chart.draw(table, this.chartOptions);
  }

  // Dragging across the chart reports how far interop moved between the dates
  // dragged over. The google-chart explorer spent the same gesture on zooming,
  // which answers a question a reader of a trendline is not really asking.
  setUpRangeMeasure() {
    const div = this.$.chart;
    div.addEventListener('mousedown', e => {
      if (!this.chart) {
        return;
      }
      this.clearRange();
      this.dragStartX = this.chartX(e);
      // The browser would otherwise start selecting text across the SVG.
      e.preventDefault();
    });
    div.addEventListener('mousemove', e => {
      if (this.dragStartX === null) {
        return;
      }
      const x = this.chartX(e);
      const ends = this.rangeEnds(this.dragStartX, x);
      this.showHighlight(ends, this.dragStartX, x);
      this.applyRange(ends);
    });
    for (const ending of ['mouseup', 'mouseleave']) {
      div.addEventListener(ending, () => {
        this.dragStartX = null;
      });
    }
  }

  chartX(e) {
    return e.clientX - this.$.chart.getBoundingClientRect().left;
  }

  clearRange() {
    this.dragStartX = null;
    this.rangeLabel = '';
    this.rangeGains = {};
    if (this.$ && this.$.highlight) {
      this.$.highlight.hidden = true;
    }
  }

  // Covers the plot area only, so a drag running past the edge of the chart
  // cannot paint over the axis labels. Once the drag spans two scored dates the
  // band snaps to them, so that it delimits exactly the range the summary
  // reports rather than wherever the pointer happens to sit.
  showHighlight(ends, startX, endX) {
    const layout = this.chart.getChartLayoutInterface();
    const area = layout.getChartAreaBoundingBox();
    const edges = ends === null
      ? [startX, endX]
      : [layout.getXLocation(ends.from.date), layout.getXLocation(ends.to.date)];
    const left = Math.max(Math.min(edges[0], edges[1]), area.left);
    const right = Math.min(Math.max(edges[0], edges[1]), area.left + area.width);
    const highlight = this.$.highlight;
    highlight.style.left = `${left}px`;
    highlight.style.top = `${area.top}px`;
    highlight.style.width = `${Math.max(right - left, 0)}px`;
    highlight.style.height = `${area.height}px`;
    highlight.hidden = false;
  }

  // Resolves a drag to the two scored dates it spans, or null while it has not
  // yet crossed from one to another.
  rangeEnds(startX, endX) {
    const layout = this.chart.getChartLayoutInterface();
    const from = this.nearestPoint(layout.getHAxisValue(Math.min(startX, endX)));
    const to = this.nearestPoint(layout.getHAxisValue(Math.max(startX, endX)));
    if (!from || !to || from === to) {
      return null;
    }

    return { from: from, to: to };
  }

  // Records the change across the dragged range for every product as well as
  // interop, since a reader comparing browsers wants to see which of them moved
  // and not only whether they converged. The gains are keyed by column name so
  // that each reads across from the score it moved, and are cleared rather than
  // nulled so the table holds its shape when nothing is selected.
  applyRange(ends) {
    if (ends === null) {
      this.rangeLabel = '';
      this.rangeGains = {};

      return;
    }

    const gains = {};
    for (const name of this.scoreColumnNames) {
      const delta = ends.to.scores[name] - ends.from.scores[name];
      if (!Number.isFinite(delta)) {
        continue;
      }
      const sign = delta > 0 ? '+' : '';
      gains[name] = `${sign}${delta.toFixed(1)}`;
    }

    this.rangeLabel =
      `${this.formatDate(ends.from.date)} to ${this.formatDate(ends.to.date)}`;
    this.rangeGains = gains;
  }

  // A drag lands between published dates, so each edge snaps to the nearest date
  // actually scored rather than interpolating a score no run produced.
  nearestPoint(value) {
    if (!this.trendPoints || !this.trendPoints.length) {
      return null;
    }
    const target = value instanceof Date ? value.getTime() : Number(value);
    if (!Number.isFinite(target)) {
      return null;
    }
    let nearest = null;
    let smallestGap = Infinity;
    for (const point of this.trendPoints) {
      const gap = Math.abs(point.date.getTime() - target);
      if (gap < smallestGap) {
        nearest = point;
        smallestGap = gap;
      }
    }
    return nearest;
  }
}
window.customElements.define(WPTInteropGraph.is, WPTInteropGraph);

export { WPTInteropGraph };
